def contracts(h):
    errors=[]
    for n in h['nodes']:
        z=n.get('information_contract')
        if z:
            for field,value,prefix in [('complete_reference',True,'INCOMPLETE_REFERENCE:'),('reference_only_cells','retained','REFERENCE_MASS_RESET:'),('spectator_influence_reuse',False,'SPECTATOR_INFLUENCE_REUSE:')]:
                if z.get(field)!=value:errors.append(prefix+key(n))
            if not z.get('partition_declared'):errors.append('UNDECLARED_PARTITION:'+key(n))
            if not z.get('conditional_refund'):errors.append('LOST_CONDITIONAL_REFUND:'+key(n))
        z=n.get('reserve_contract')
        if z:
            if z.get('charged_items')!=z.get('allowed_charges'):errors.append('RESERVE_REUSE:'+key(n))
            for field,value,prefix in [('claims_positive_child_slack',False,'UNPROVED_CHILD_CAPACITY:'),('capacity_evidence','Dedicated local bound only','ROOT_BOUND_PROMOTED_TO_CAPACITY:'),('terminal_gate_mask_payment','UNRESOLVED','UNPAID_TERMINAL_MASK:')]:
                if z.get(field)!=value:errors.append(prefix+key(n))
        z=n.get('history_contract')
        if z:
            for field,value,prefix in [('phase_available',True,'MISSING_PHASE:'),('arbitrary_supplied_reference',False,'UNPROVED_REFERENCE_EXTENSION:'),('executed_cost_cancellation',False,'EXECUTED_COST_REFUND:'),('descendant_bank_renewal',False,'BANK_RENEWAL:'),('terminal_entropy','both complete terminals retained','TERMINAL_DEBT_DROPPED:'),('actual_encoder_interaction','included','ENCODER_INTERACTION_ERASED:')]:
                if z.get(field)!=value:errors.append(prefix+key(n))
            if z.get('depth_scope') not in ['one data query before fixed encoder resolution','two distinct data queries before fixed encoder resolution']:errors.append('UNPROVED_HISTORY_DEPTH:'+key(n))
    return errors
